-- Previous analyses: one row per saved analysis, private to its owner.
-- Metadata only. Recordings are never uploaded; the browser keeps the signal data.
--
-- local_id is generated by the browser so the same analysis can be synced from
-- several tabs/devices without creating duplicates. Rows are immutable: there is
-- no UPDATE grant, so re-syncing an existing analysis is a no-op (23505).
create table public.analyses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  local_id text not null check (local_id = btrim(local_id) and char_length(local_id) between 1 and 100),
  filename text not null check (filename = btrim(filename) and char_length(filename) between 1 and 200),
  duration_sec numeric not null check (duration_sec > 0 and duration_sec <= 86400),
  channels integer not null check (channels between 1 and 1024),
  sample_rate numeric not null check (sample_rate > 0 and sample_rate <= 1000000),
  created_at timestamptz not null default now()
);

create unique index analyses_user_local_idx on public.analyses (user_id, local_id);
create index analyses_user_created_idx on public.analyses (user_id, created_at desc);

alter table public.analyses enable row level security;
revoke all on table public.analyses from public, anon, authenticated;
grant select, insert, delete on table public.analyses to authenticated;

create policy "Read own analyses" on public.analyses for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "Save own analyses" on public.analyses for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy "Delete own analyses" on public.analyses for delete to authenticated
  using ((select auth.uid()) = user_id);
